ext small{color:#8f877d;font-size:8px;letter-spacing:.1em}.replay{font-size:9px;color:var(--gold);border:1px solid #4c3c25;border-radius:999px;padding:5px 7px;white-space:nowrap}.section{padding:13px;position:relative;z-index:2}.label{font-size:9px;color:#8f877d;letter-spacing:.15em;margin-bottom:8px}.bars{display:grid;gap:9px}.bar h3{font-size:12px;margin:0 0 5px;display:flex;justify-content:space-between}.cells{display:grid;grid-template-columns:repeat(20,1fr);gap:2px}.cell{height:10px;border:1px solid #2b272d;background:#111014;border-radius:2px}.cell.k{background:linear-gradient(#5e242a,#351519);border-color:#6c2b31}.cell.c{background:linear-gradient(#31525e,#182d34);border-color:#426b78}.cell.gold{box-shadow:0 0 6px #cdaa6333;border-color:#9a7a43}.ticket{margin-top:14px;border:1px solid #4b3b28;border-radius:13px;background:linear-gradient(145deg,#171216,#0d0b0e);padding:13px;position:relative;overflow:hidden;min-height:88px}.ticket:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(9,8,11,.98) 0 50%,rgba(9,8,11,.65) 72%,rgba(9,8,11,.25) 100%);pointer-events:none}.ticketart{position:absolute;right:-8px;top:-28px;width:145px;height:145px;object-fit:cover;object-position:50% 18%;opacity:.14;filter:saturate(.7) contrast(1.07);transition:.35s}.ticketcontent{position:relative;z-index:2}.ticket strong{font-size:15px}.ticket small{display:block;color:#a99d8f;margin-top:4px;font-size:10px}.ticket .cat{color:var(--gold2);font-size:9px;letter-spacing:.12em;margin-bottom:5px}.codexrow{display:flex;align-items:center;justify-content:space-between;padding:11px 13px;border-top:1px solid #2a232a;border-bottom:1px solid #2a232a;position:relative;z-index:2}.codexrow span{font-size:12px}.codexrow small{color:#91877d}.revive{padding:14px;position:relative;z-index:2}.revivebox{border:1px solid #3d332b;border-radius:14px;background:linear-gradient(180deg,#151214,#0e0c0e);padding:15px 14px 14px;position:relative;overflow:hidden;min-height:158px}.reviveart{position:absolute;right:-12px;bottom:-16px;width:160px;height:190px;object-fit:cover;object-position:50% 10%;opacity:.13;filter:saturate(.8) contrast(1.03);-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 28%,#000 100%);mask-image:linear-gradient(90deg,transparent 0,#000 28%,#000 100%);transition:.35s}.haloring{position:absolute;right:16px;top:14px;width:92px;height:46px;border:1px solid rgba(239,213,139,.30);border-radius:92px 92px 0 0;border-bottom:none;opacity:.45;transition:.35s}.revivetext{position:relative;z-index:2;max-width:66%}.revive h3{margin:7px 0 5px;font-size:14px}.revive p{margin:0;color:#9e9488;font-size:10px;line-height:1.6}.btn{display:block;width:100%;margin-top:13px;padding:10px;border:1px solid #7e6137;border-radius:9px;background:#1a1412;color:var(--gold2);font-weight:700;position:relative;z-index:2}.watermark{text-align:center;padding:15px 0 2px;color:rgba(205,170,99,.11);font-size:9px;letter-spacing:.22em}.identity{display:none;padding:13px;border-top:1px solid var(--line);background:#0e0c10}.identity.open{display:grid;grid-template-columns:96px 1fr;gap:12px;align-items:center}.identity img{width:96px;height:126px;object-fit:cover;object-position:50% 14%;border-radius:12px;border:1px solid #6d5632}.identity b{font-size:13px}.identity p{font-size:10px;color:#9e9488;line-height:1.6;margin:5px 0 0}.controls{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:12px}.controls button{background:#151217;border:1px solid #3d333c;color:#d7cbb6;border-radius:9px;padding:9px 4px;font-size:10px}.observe .seal{box-shadow:0 0 18px #efd58b38}.observe .ticketart{opacity:.20}.intervene .seal{box-shadow:0 0 24px #efd58b55}.intervene .revivebox{border-color:#8c6a3b;box-shadow:0 0 22px #cdaa6317}.intervene .reviveart{opacity:.32}.intervene .haloring{opacity:.82;border-color:#cdaa63}.quiet .reviveart{opacity:.10}@media(max-width:360px){.qtext div{font-size:11px}.portrait{width:38px;height:38px}.revivetext{max-width:70%}.identity.open{grid-template-columns:78px 1fr}.identity img{width:78px;height:106px}.controls{grid-template-columns:repeat(2,1fr)}}

:host{display:block;width:100%;color-scheme:dark;max-width:440px;margin:12px auto;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.5}
[hidden]{display:none!important}.surface{padding:0;background:none}.card{width:100%;min-width:0}.title,.bar h3 span{min-width:0}.title b{font-size:14px}.title small{font-size:8px;overflow-wrap:anywhere}.seal{opacity:.4}.observe .seal{opacity:.67}.intervene .seal{opacity:.85}
button{font:inherit;cursor:pointer;touch-action:manipulation;color:var(--text);min-height:44px;min-width:44px}button:disabled{cursor:default;opacity:.46}button:focus-visible,summary:focus-visible{outline:2px solid var(--gold2);outline-offset:3px}.replay{background:none;font-size:10px;padding:6px;white-space:normal;width:72px;flex-shrink:0}.quote{min-height:58px}.qtext div{font-size:12px;line-height:1.6}.portrait{width:36px;height:36px}.bar h3{flex-wrap:wrap;gap:4px;font-size:12px}.cells{width:100%;grid-template-columns:repeat(20,minmax(0,1fr))}.cell{min-width:0}.cell.historical{opacity:.4}.cell.fresh{animation:cell-once .6s ease-out}.legend{font-size:11px;line-height:1.7;color:#b4a89a;margin:8px 0 0;overflow-wrap:anywhere}.empty{font-size:13px;color:var(--muted)}
.codexrow{width:100%;background:transparent;color:var(--text);text-align:left;border-left:0;border-right:0;gap:6px;flex-wrap:wrap}.codexrow small{font-size:11px}.codex{padding:12px;max-height:56vh;overflow:auto;overscroll-behavior:contain;scrollbar-color:#796137 #151217;scrollbar-width:thin;touch-action:pan-y}.codex h3{font-size:12px;color:var(--gold);letter-spacing:.16em}.bookmarks{display:flex;gap:6px;overflow:auto;padding:4px 0 8px;overscroll-behavior-x:contain}.bookmarks button{flex:none;background:#151116;border:1px solid var(--line);border-radius:8px;padding:6px 10px;font-size:12px}.bookmarks button[aria-pressed=true]{border-color:var(--gold);color:var(--gold2)}.entries{display:grid;gap:8px;margin-top:10px}.entry{border:1px solid #514337;border-radius:9px;min-height:76px;padding:9px 11px;display:flex;flex-direction:column;gap:3px;overflow-wrap:anywhere}.entry b{font-size:14px}.entry small{font-size:10px;color:#b2a798}.entry.unknown{border-color:var(--line)}.entry.unknown b{color:#b8aea2}.pagination{display:flex;align-items:center;justify-content:space-between;gap:8px;padding-top:12px;font-size:12px}.pagination button{background:#161118;border:1px solid #5a4731;border-radius:8px;padding:5px 12px}
.ticket{width:100%;min-width:0;perspective:800px}.ticket strong{overflow-wrap:anywhere}.ticket.new-ticket{animation:ticket-once .86s ease-out}.ticket .text-button{font-size:11px}.ticketart{pointer-events:none}.reviveart{pointer-events:none;object-position:50% 8%;clip-path:inset(0 0 28% 0);width:150px;height:210px;bottom:-50px}.revivebox{min-height:148px}.revivebox.dead .reviveart{opacity:.3}.revivebox.dead{border-color:#8c6a3b}.revivebox.dead .haloring{opacity:.8}.revivetext{max-width:70%}.revive p{font-size:11px}.btn{min-height:46px;font-size:13px}.settings{padding:0 13px 12px;font-size:11px;color:#b7aa96}.settings summary{min-height:44px;display:flex;align-items:center;cursor:pointer}.text-button{background:transparent;color:var(--gold2);border:1px solid #4f3f2b;padding:7px 10px;border-radius:8px;margin:6px 6px 0 0;font-size:12px}.feedback:empty{display:none}.feedback{padding:10px 13px;font-size:12px;color:#dac28f}.image-fallback.portrait{border:1px solid var(--gold);background:radial-gradient(circle,#cdaa6355,transparent 70%)}
